-- ===== 4_rounds.sql =====
-- Rounds from the stats dump bf2stats_2026_10-16.
-- * Rounds matching a session you logged by hand get the real date and a link to the
--   stats round; that session keeps its size, bots and difficulty.
-- * The other 3-8 player rounds are inserted new. Size is inferred (see scripts/bf2stats_config.py),
--   difficulty is left blank: fill it in with Edit in admin.
-- * Round duration is (re)filled in for every round with a log row here, not just new ones,
--   so it stays correct as the raw dump's duration figure changes or gets backfilled.
-- Safe to re-run (each round is linked by stats_round_id and only ever imported once).

alter table public.bf2_game_logs add column if not exists stats_round_id bigint unique;
alter table public.bf2_game_logs add column if not exists duration_seconds integer;

-- New rounds
insert into public.bf2_game_logs (map_id, player_count, map_size, bot_count, result, difficulty, played_at, notes, stats_round_id) values ((select id from public.bf2_maps where sort_order = 60), 3, 16, 30, 'win', null, '2026-10-15', 'Imported from stats round #120 (size assumed)', 120) on conflict (stats_round_id) do nothing;  -- zatar_wetlands_ii
insert into public.bf2_game_logs (map_id, player_count, map_size, bot_count, result, difficulty, played_at, notes, stats_round_id) values ((select id from public.bf2_maps where sort_order = 26.5), 4, 16, 40, 'win', null, '2026-10-15', 'Imported from stats round #121 (size assumed)', 121) on conflict (stats_round_id) do nothing;  -- aix_refinery
insert into public.bf2_game_logs (map_id, player_count, map_size, bot_count, result, difficulty, played_at, notes, stats_round_id) values ((select id from public.bf2_maps where sort_order = 17), 4, 16, 40, 'win', null, '2026-10-15', 'Imported from stats round #122 (size assumed)', 122) on conflict (stats_round_id) do nothing;  -- ghost_town
insert into public.bf2_game_logs (map_id, player_count, map_size, bot_count, result, difficulty, played_at, notes, stats_round_id) values ((select id from public.bf2_maps where sort_order = 48), 4, 16, 40, 'win', null, '2026-10-16', 'Imported from stats round #123 (size assumed)', 123) on conflict (stats_round_id) do nothing;  -- tng_the_dam_flood

